"use strict";(globalThis.webpackChunkdocs_next=globalThis.webpackChunkdocs_next||[]).push([[84608],{72223(e){e.exports=JSON.parse('{"tag":{"label":"bitnami","permalink":"/docs-next/pr-preview/pr-416/docs/tags/bitnami","allTagsPath":"/docs-next/pr-preview/pr-416/docs/tags","count":1,"items":[{"id":"blueprints/by-use-case/security/encrypt-cce-secrets-with-sealed-secrets","title":"Encrypt CCE Secrets with Sealed Secrets","description":"Managing sensitive data in Kubernetes clusters is a recurring challenge, especially when configuration needs to be versioned and shared across teams. Standard Kubernetes secrets are not designed for safe storage in source control, as they are only base64-encoded (not encrypted) and can be easily decoded back to plain text. This creates a gap between secure secret handling and common GitOps workflows.","permalink":"/docs-next/pr-preview/pr-416/docs/blueprints/by-use-case/security/encrypt-cce-secrets-with-sealed-secrets"}],"unlisted":false}}')}}]);